using Seamless.Management;
using Seamless.Management.Server;

namespace Management.Tests;

[Collection("AuditStorage")]
public sealed class ManagementSourceAuthorization{
    private static string Root()=>Path.Combine(Environment.GetEnvironmentVariable("SEAMLESS_MANAGEMENT_TEST_ROOT")!,Guid.NewGuid().ToString("N"));
    private static Seamless.Management.Server.ManagementService Setup(ManagementStore store,out UserAccount admin,out UserAccount viewer){var service=new Seamless.Management.Server.ManagementService(store);admin=service.Authenticate(service.Login(new("admin","TestPassword-123")).Token);NativeWorkflow.Publish(service,admin,NativeWorkflow.Database());var query=new Definition("private-query","Native",DefinitionKind.Query,"Model.PrivateQueries","Run",new("1",[new("PrivateQuery.cs","using Seamless.Management.Server;namespace Model;public static class PrivateQueries{public static int Run(ManagementExecutionContext context){if(\"PRIVATE_SOURCE_MARKER_731\".Length>0){return 42;}return 0;}}")],[]));NativeWorkflow.Publish(service,admin,query);service.ChangeUser(admin,new("viewer","ViewerPassword-123",[new("Native",ManagementPermission.View|ManagementPermission.Execute|ManagementPermission.Validate)]));viewer=service.Authenticate(service.Login(new("viewer","ViewerPassword-123")).Token);return service;}
    [Theory][InlineData("definition")][InlineData("version")][InlineData("analysis")][InlineData("plans")][InlineData("objectSource")]
    public void ViewerCannotReadCodeOrDerivedDebugInformation(string operation){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=Setup(store,out var admin,out var viewer);var denied=Assert.Throws<ManagementException>(()=>{switch(operation){case "definition":_=service.GetDefinition(viewer,"private-query");break;case "version":_=service.Version(viewer,"private-query",1);break;case "analysis":_=service.AnalyzePublished(viewer,"private-query");break;case "plans":_=service.Plans(viewer,"private-query");break;case "objectSource":_=service.ObjectSource(viewer,new("db:db",ObjectId:"Rows"));break;}});Assert.Equal("Permission",denied.Code);Assert.Contains("PRIVATE_SOURCE_MARKER_731",service.GetDefinition(admin,"private-query").Definition.Source.Files[0].Text);}
    [Fact]public void StructureDoesNotExposeSourceLocationsToViewer(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=Setup(store,out var admin,out var viewer);var detail=service.ObjectDetails(viewer,new("db:db",ObjectId:"Rows"));Assert.Contains(detail.Columns,item=>item.Name=="Value");Assert.False(detail.Source.Available);Assert.Equal("Permission",detail.Source.UnavailableReason);Assert.Null(detail.Source.Path);Assert.Equal(0,detail.Source.Start);Assert.Equal(0,detail.Source.Length);Assert.True(service.ObjectDetails(admin,new("db:db",ObjectId:"Rows")).Source.Available);}
    [Fact]public void PublicContractDoesNotReturnImplementationAndAllowsExecuteOnly(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=Setup(store,out var admin,out var viewer);var info=service.DefinitionInfo(viewer,"private-query");Assert.Equal("Model.PrivateQueries",info.Definition.EntryType);Assert.Equal("Run",info.Definition.EntryMember);Assert.Equal(1,info.Version);Assert.Equal(service.GetDefinition(admin,"private-query").ArtifactHash,info.ArtifactHash);Assert.NotNull(info.Method);Assert.Null(info.Method.QueryTemplate);Assert.DoesNotContain("PRIVATE_SOURCE_MARKER_731",System.Text.Json.JsonSerializer.Serialize(info,ManagementJson.Options));service.ChangeUser(admin,new("executor","ExecutorPassword-123",[new("Native",ManagementPermission.Execute)]));var executor=service.Authenticate(service.Login(new("executor","ExecutorPassword-123")).Token);Assert.Equal(info,service.DefinitionInfo(executor,"private-query"));Assert.Equal("Permission",Assert.Throws<ManagementException>(()=>service.DefinitionInfo(executor,"db")).Code);Assert.Equal("Permission",Assert.Throws<ManagementException>(()=>service.GetDefinition(executor,"private-query")).Code);}
    [Fact]public void SeparateViewAndEditGrantsAllowDeveloperSource(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=Setup(store,out var admin,out _);service.ChangeUser(admin,new("developer","DeveloperPassword-123",[new("Native",ManagementPermission.View),new("*",ManagementPermission.Edit)]));var developer=service.Authenticate(service.Login(new("developer","DeveloperPassword-123")).Token);Assert.Contains("PRIVATE_SOURCE_MARKER_731",service.GetDefinition(developer,"private-query").Definition.Source.Files[0].Text);Assert.True(service.ObjectSource(developer,new("db:db",ObjectId:"Rows")).Location.Available);}
    [Fact]public async Task LocalOperatingSystemIdentityDoesNotBypassSourceAuthorization(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=Setup(store,out _,out _);using var key=System.Security.Cryptography.RSA.Create(2048);var request=new System.Security.Cryptography.X509Certificates.CertificateRequest("CN=localhost",key,System.Security.Cryptography.HashAlgorithmName.SHA256,System.Security.Cryptography.RSASignaturePadding.Pkcs1);using var certificate=request.CreateSelfSigned(DateTimeOffset.UtcNow.AddMinutes(-1),DateTimeOffset.UtcNow.AddDays(1));await using var server=new Seamless.Management.Server.ManagementServer(service,certificate,new(System.Net.IPAddress.Loopback,0),"viewer");server.Start();var client=ManagementClient.ForLocalPipe(server.PipeName!);Assert.Equal("viewer",(await client.LocalIdentityAsync()).Name);Assert.Equal("Permission",(await Assert.ThrowsAsync<ManagementException>(()=>client.CallAsync<DefinitionVersion>("definition","Native",new{id="private-query"}))).Code);Assert.Equal("Run",(await client.CallAsync<PublishedDefinitionInfo>("definitionInfo","Native",new{id="private-query"})).Definition.EntryMember);Assert.Equal("Permission",(await client.CallAsync<CatalogObjectDetails>("catalogDetails","Native",new CatalogRequest("db:db",ObjectId:"Rows"))).Source.UnavailableReason);}
    [Fact]public void SourceRestrictionKeepsExecutionAndValidationDatabaseAvailable(){using var store=ManagementStore.Initialize(Root(),"admin","TestPassword-123");using var service=Setup(store,out _,out var viewer);Assert.Equal(42,Assert.Single(service.Execute(viewer,new("private-query",null,ManagementJson.Element(new{})),CancellationToken.None)).Value.GetInt32());var validation=service.CreateValidation(viewer,"db");Assert.Equal("Native",validation.Database);Assert.Equal("private-query",Assert.Single(service.Definitions(viewer).Items,item=>item.Definition.Kind==DefinitionKind.Query).Definition.Id);}
}
